WITH employees_by_department AS (SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary, COUNT(DISTINCT salary) AS unique_job_titles FROM employees GROUP BY dept_id) SELECT departments.id, departments.budget, departments.location, employees_by_department.stddev_salary, employees_by_department.unique_job_titles FROM departments LEFT JOIN employees_by_department ON departments.id = employees_by_department.dept_id WHERE employees_by_department.unique_job_titles >= 4;
